var o = new ExportOptionsAVIF();
o.losslessCompression = false;
o.imageQuality = 50;
o.PPI = 144;
o.isTransparent = true;
app.activeDocument.exportFile(new File("~/Desktop/hero.avif"), ExportType.AVIF, o);

var o = new ExportOptionsGIF();
o.colorCount = 32;
o.colorDither = ColorDitherMethod.NOREDUCTION;
o.transparency = true;
o.artBoardClipping = true;
app.activeDocument.exportFile(new File("~/Desktop/badge.gif"), ExportType.GIF, o);

var o = new ExportOptionsJPEG();
o.qualitySetting = 90;
o.horizontalScale = o.verticalScale = 300;
o.antiAliasing = true;
o.artBoardClipping = true;
app.activeDocument.exportFile(new File("~/Desktop/proof.jpg"), ExportType.JPEG, o);

var o = new ExportOptionsPhotoshop();
o.imageColorSpace = ImageColorSpace.CMYK;
o.resolution = 300;
o.writeLayers = true;
o.editableText = true;
o.warnings = false;
app.activeDocument.exportFile(new File("~/Desktop/layout.psd"), ExportType.PHOTOSHOP, o);

var o = new ExportOptionsPNG24();
o.transparency = true;
o.antiAliasing = true;
o.artBoardClipping = true;
o.horizontalScale = o.verticalScale = 200;
app.activeDocument.exportFile(new File("~/Desktop/logo@2x.png"), ExportType.PNG24, o);

var o = new ExportOptionsPNG8();
o.colorCount = 16;
o.colorDither = ColorDitherMethod.NOREDUCTION;
o.transparency = true;
o.artBoardClipping = true;
app.activeDocument.exportFile(new File("~/Desktop/icon.png"), ExportType.PNG8, o);

var o = new ExportOptionsSVG();
o.fontType = SVGFontType.OUTLINEFONT;
o.embedRasterImages = true;
o.documentEncoding = SVGDocumentEncoding.UTF8;
o.coordinatePrecision = 2;
app.activeDocument.exportFile(new File("~/Desktop/art.svg"), ExportType.SVG, o);

var o = new ExportOptionsTIFF();
o.imageColorSpace = ImageColorSpace.CMYK;
o.resolution = 300;
o.lZWCompression = true;
o.saveMultipleArtboards = true;
o.artboardRange = "1";
app.activeDocument.exportFile(new File("~/Desktop/print.tif"), ExportType.TIFF, o);

var o = new ExportOptionsWebOptimizedSVG();
o.fontType = SVGFontType.OUTLINEFONT;
o.svgMinify = true;
o.svgResponsive = false;
o.svgId = SVGIdType.SVGIDUNIQUE;
o.coordinatePrecision = 2;
app.activeDocument.exportFile(new File("~/Desktop/icon.svg"), ExportType.WOSVG, o);

var o = new ExportOptionsWebP();
o.losslessCompression = false;
o.imageQuality = 80;
o.PPI = 144;
o.isTransparent = true;
app.activeDocument.exportFile(new File("~/Desktop/banner.webp"), ExportType.WEBP, o);

var doc = app.activeDocument;
var o = new ImageCaptureOptions();
o.resolution = 300;
o.antiAliasing = true;
o.transparency = true;
doc.imageCapture(new File("~/Desktop/item.png"), doc.pageItems[0].visibleBounds, o);

var o = new OpenOptions();
o.updateLegacyText = true;
o.addToRecentFiles = false;
app.userInteractionLevel = UserInteractionLevel.DONTDISPLAYALERTS;
var doc = app.open(new File("~/Desktop/old.ai"), DocumentColorSpace.CMYK, o);

var cad = app.preferences.AutoCADFileOptions;
cad.globalScaleOption = AutoCADGlobalScaleOption.ScaleByValue;
cad.unit = AutoCADUnit.Millimeters;
cad.unitScaleRatio = 1.0;
cad.scaleLineweights = true;
var doc = app.open(new File("~/Desktop/plan.dwg"));

var pdf = app.preferences.PDFFileOptions;
pdf.pageToOpen = 3;
pdf.pDFCropToBox = PDFBoxType.PDFTRIMBOX;
var doc = app.open(new File("~/Desktop/brochure.pdf"));
pdf.pageToOpen = 1;

var ps = app.preferences.photoshopFileOptions;
ps.preserveLayers = true;
ps.preserveHiddenLayers = false;
ps.layerComp = "Version B";
var doc = app.open(new File("~/Desktop/mockup.psd"));

var o = new EPSSaveOptions();
o.compatibility = Compatibility.ILLUSTRATOR10;
o.embedAllFonts = true;
o.embedLinkedFiles = true;
o.cmykPostScript = true;
app.activeDocument.saveAs(new File("~/Desktop/logo.eps"), o);

var o = new FXGSaveOptions();
o.version = FXGVersion.VERSION2PT0;
o.preserveEditingCapabilities = false;
o.includeUnusedSymbols = false;
app.activeDocument.saveAs(new File("~/Desktop/ui.fxg"), o);

var o = new IllustratorSaveOptions();
o.compatibility = Compatibility.ILLUSTRATOR17;
o.pdfCompatible = true;
o.embedLinkedFiles = true;
o.compressed = true;
app.activeDocument.saveAs(new File("~/Desktop/handoff_cc.ai"), o);

var o = new PDFSaveOptions();
o.pDFPreset = "[High Quality Print]";
o.preserveEditability = false;
o.trimMarks = true;
o.bleedOffsetRect = [8.504, 8.504, 8.504, 8.504];
o.artboardRange = "1-2";
app.activeDocument.saveAs(new File("~/Desktop/print.pdf"), o);

var doc = app.activeDocument;
var it = doc.pageItems[0];
var p = it.position;          // [x, y]
it.position = [p[0] + 36, p[1] - 36]; // right and down 0.5 in
var q = doc.convertCoordinate(p, CoordinateSystem.ARTBOARDCOORDINATESYSTEM, CoordinateSystem.DOCUMENTCOORDINATESYSTEM);

var r = app.activeDocument.artboards[0].artboardRect; // [l, t, r, b]
var w = r[2] - r[0];
var h = r[1] - r[3];
$.writeln(w + " x " + h + " pt (" + r.length + " values)");

var inks = app.activeDocument.inkList;
for (var i = 0; i < inks.length; i++) {
  var k = inks[i].inkInfo;
  $.writeln(inks[i].name + " " + k.kind + " " + k.frequency + " lpi @ " + k.angle);
}

var inks = app.activeDocument.inkList;
for (var i = 0; i < inks.length; i++)
  if (inks[i].inkInfo.kind == InkType.CUSTOMINK) inks[i].inkInfo.printingStatus = InkPrintStatus.CONVERTINK;
var sep = new PrintColorSeparationOptions();
sep.inkList = inks;

var sizes = app.printerList[0].printerInfo.paperSizes;
for (var i = 0; i < sizes.length; i++)
  $.writeln(sizes[i].name + ": " + sizes[i].paperInfo.width + " x " + sizes[i].paperInfo.height + " pt");

var p = app.printerList[0].printerInfo.paperSizes[0];
var pi = p.paperInfo;
$.writeln(p.name + " " + pi.width + "x" + pi.height + " custom=" + pi.customPaper);

var info = app.getPPDFileInfo(app.PPDFileList[0].name);
$.writeln("PS level " + info.languageLevel + ": " + info.PPDFilePath.fsName);
for (var i = 0; i < info.screenList.length; i++) $.writeln(info.screenList[i].name);

var cm = new PrintColorManagementOptions();
cm.intent = PrintColorIntent.RELATIVECOLORIMETRIC;
var po = new PrintOptions();
po.colorManagementOptions = cm;
app.activeDocument.print(po);

var sep = new PrintColorSeparationOptions();
sep.colorSeparationMode = PrintColorSeparationMode.HOSTBASEDSEPARATION;
sep.convertSpotColors = true;
var po = new PrintOptions();
po.colorSeparationOptions = sep;
app.activeDocument.print(po);

var co = new PrintCoordinateOptions();
co.fitToPage = true;
co.orientation = PrintOrientation.AUTOROTATE;
var po = new PrintOptions();
po.coordinateOptions = co;
app.activeDocument.print(po);

var list = app.printerList;
for (var i = 0; i < list.length; i++)
  $.writeln(list[i].name + " PS=" + list[i].printerInfo.postScriptLevel);

var info = app.printerList[0].printerInfo;
if (info.printerType == PrinterTypeEnum.POSTSCRIPTPRINTER)
  $.writeln("PS, in-RIP seps: " + info.inRIPSeparationSupport);

var fl = new PrintFlattenerOptions();
fl.flatteningBalance = 75;
fl.rasterizationResolution = 300;
fl.clipComplexRegions = true;
var po = new PrintOptions();
po.flattenerOptions = fl;
app.activeDocument.print(po);

var fo = new PrintFontOptions();
fo.downloadFonts = PrintFontDownloadMode.DOWNLOADCOMPLETE;
var po = new PrintOptions();
po.fontOptions = fo;
app.activeDocument.print(po);

var job = new PrintJobOptions();
job.copies = 2;
job.printAllArtboards = false;
job.artboardRange = "1-3";
var po = new PrintOptions();
po.jobOptions = job;
app.activeDocument.print(po);

var po = new PrintOptions();
po.printerName = app.printerList[0].name;
var job = new PrintJobOptions();
job.copies = 1;
po.jobOptions = job;
app.activeDocument.print(po);

var pm = new PrintPageMarksOptions();
pm.trimMarks = true;
pm.registrationMarks = true;
pm.bleedOffsetRect = [8.504, 8.504, 8.504, 8.504];
var po = new PrintOptions();
po.pageMarksOptions = pm;
app.activeDocument.print(po);

var pp = new PrintPaperOptions();
pp.name = app.printerList[0].printerInfo.paperSizes[0].name;
var po = new PrintOptions();
po.paperOptions = pp;
app.activeDocument.print(po);

var ps = new PrintPostScriptOptions();
ps.postScriptLevel = PrinterPostScriptLevelEnum.PSLEVEL3;
ps.binaryPrinting = true;
var po = new PrintOptions();
po.postScriptOptions = ps;
app.activeDocument.print(po);

var info = app.getPPDFileInfo(app.PPDFileList[0].name);
var s = info.screenList;
for (var i = 0; i < s.length; i++) $.writeln(s[i].name + " " + s[i].screenInfo.frequency + " lpi");
